import{_ as n,a as i,b as t,c as s,d as r,e as a,f as d,g as l}from"./chunks/weather-heating-meteored.DOiN_qir.js";import{_ as o,o as h,c as g,a3 as u}from"./chunks/framework.BlfGB29P.js";const z=JSON.parse('{"title":"Wetter und Heizung","description":"Das optionale Diagramm-Widget-Paket installieren und konfigurieren.","frontmatter":{"title":"Wetter und Heizung","description":"Das optionale Diagramm-Widget-Paket installieren und konfigurieren."},"headers":[],"relativePath":"projects/grafik-visual-studio/weather-heating.md","filePath":"projects/grafik-visual-studio/weather-heating.md","lastUpdated":1792861021000}'),p={name:"projects/grafik-visual-studio/weather-heating.md"};function c(k,e,b,m,E,f){return h(),g("div",null,[...e[0]||(e[0]=[u('<h1 id="wetter-und-heizung" tabindex="-1">Wetter und Heizung <a class="header-anchor" href="#wetter-und-heizung" aria-label="Permalink to &quot;Wetter und Heizung&quot;">​</a></h1><p>Pakete und Zusatztools werden zentral auf <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a> angeboten. Diese Open-Source-Seite enthält Beschreibung und Anleitung; der Download erfolgt über den Paketkatalog.</p><p><strong>Inspiriert von den ioBroker-Widgets „Wetter und Heizung“ von <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">rg-engineering</a>.</strong> Die Studio-Widgets sind eine eigene Umsetzung für Home Assistant.</p><p>Ab <strong>Studio 0.1.194</strong> kannst du das Paket <strong>Wetter und Heizung 1.7.0</strong> nachinstallieren. Es enthält <strong>Allgemeines Diagramm</strong>, <strong>Balkendiagramm für zwei Wochen</strong>, <strong>Wetter-Widget</strong>, <strong>Übersicht über Heizräume</strong>, <strong>METEORED-Wetter-Widget</strong>, <strong>Fensterstatus-Übersicht</strong>, <strong>Meinen Vermieter informieren</strong> und <strong>Allgemeine Heizparameter</strong>. Funktionsreferenz ist <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-weather-and-heating</a>; das Studio verwendet eigene Darstellungen. Weitere Wetter- und Heizungswidgets sowie ioBroker-spezifische Adapterbindungen sind noch nicht enthalten.</p><h2 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h2><p>Lade <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=de" target="_blank" rel="noreferrer">ugso.weather-heating.wg</a> herunter. Öffne <strong>Einstellungen → Widget-Pakete → Lokales .wg / .wg.zip installieren</strong> und wähle die Datei. Nach dem Neuladen erscheint ein eigenes Set mit automatisch vergebener Farbe. Die Farbzuordnung bleibt in diesem Browser erhalten, auch bei Entfernen und Neuinstallation. Die 74 integrierten Widgets bleiben verfügbar.</p><h2 id="diagramm-konfigurieren" tabindex="-1">Diagramm konfigurieren <a class="header-anchor" href="#diagramm-konfigurieren" aria-label="Permalink to &quot;Diagramm konfigurieren&quot;">​</a></h2><p>Ein installiertes Paket 1.0.0 bis 1.6.0 kannst du über denselben Import auf 1.7.0 aktualisieren. Vorhandene Widgets und Projektwerte bleiben erhalten. Updates dürfen ausschließlich neue Widgets ergänzen; Änderungen bestehender Definitionen oder Downgrades werden abgewiesen.</p><h2 id="allgemeine-heizparameter" tabindex="-1">Allgemeine Heizparameter <a class="header-anchor" href="#allgemeine-heizparameter" aria-label="Permalink to &quot;Allgemeine Heizparameter&quot;">​</a></h2><p>Das Widget zeigt acht Zeilen: <strong>Heizperiode aktiv</strong>, <strong>Heute Feiertag</strong>, <strong>Anwesend</strong>, <strong>Jetzt feiern</strong>, <strong>Gäste anwesend</strong>, <strong>Urlaub zu Hause</strong>, <strong>Urlaub abwesend</strong> und <strong>Kaminmodus</strong>. Unter <strong>Heizparameter-Entitäten</strong> weist du jeder Zeile ihre eigene HA-Entität zu. Die optional gewählte Raum-Entität erscheint als Text über den Schaltern; sie wird nicht verändert. Die ursprüngliche <code>heatingcontrol.0</code>-Instanz ist nicht erforderlich.</p><p>In der Runtime sind verfügbare <code>input_boolean.*</code> und <code>switch.*</code> mit Zustand <code>on</code>/<code>off</code> schaltbar. Jede Aktion setzt ausschließlich die angeklickte Entität ein oder aus. Sensoren, beispielsweise <code>binary_sensor.*</code>, dienen nur als Anzeige. Während eines Schaltbefehls bleibt die entsprechende Entität gesperrt; Fehler werden über den bestehenden Studio-Schaltstatus gemeldet. <strong>Allgemein → Schreibgeschützt</strong> sperrt alle Schaltaktionen. <strong>Ohne Karte</strong> entfernt den äußeren Kartenhintergrund.</p><p>Ungebundene Zeilen sind in der Runtime deaktiviert und als <strong>Ungebunden</strong> markiert. Fehlende oder nicht verfügbare gebundene Werte zeigen <strong>Unbekannt</strong> mit einem gestreiften Schalter. Es wird kein Vorschauwert als Live-Wert eingesetzt. Die Checkboxen unter <strong>Vorschau</strong> gelten ausschließlich im ungebundenen Editor; auch dort werden keine Schaltbefehle gesendet.</p><p>Alle neun Entitätsbindungen, Vorschauwerte, Schreibschutz und Darstellungsoptionen bleiben in Projekt und Widget-Export erhalten. Das Widget bündelt deine vorhandenen HA-Entitäten; es berechnet keine Heizzeiten, Feiertage oder Anwesenheit und enthält keine eigene Heizregelung.</p><p><img src="'+n+'" alt="Allgemeine Heizparameter und ihre Entitätsbindungen"></p><h2 id="meinen-vermieter-informieren" tabindex="-1">Meinen Vermieter informieren <a class="header-anchor" href="#meinen-vermieter-informieren" aria-label="Permalink to &quot;Meinen Vermieter informieren&quot;">​</a></h2><p>Das Widget bietet <strong>Priorität</strong> (Information, Wichtig, Dringend), <strong>Nachricht</strong> und <strong>Senden</strong>. Im Editor ist es eine Vorschau. In der Runtime wird ausschließlich beim bewussten Senden an Home Assistant übergeben. Leere Nachrichten und wiederholte Klicks während einer laufenden Übergabe werden abgefangen. Bei einem Fehler bleibt die Nachricht zum erneuten Versuch erhalten; bei HA-Annahme wird sie geleert. Die Annahme bestätigt keine Zustellung.</p><p>Unter <strong>Allgemein</strong> findest du <strong>Ohne Karte</strong>, <strong>Nachrichtentyp</strong>, <strong>HA-Benachrichtigungsaktion</strong>, <strong>Benachrichtigungs-Entität</strong> und <strong>Betreff / Nachrichtenüberschrift</strong>. Beispiel: Aktion <code>notify.send_message</code> mit deiner konkreten Entität <code>notify.vermieter</code>. Alternativ kannst du eine eingerichtete benannte Aktion wie <code>notify.vermieter_email</code> verwenden; dann bleibt das Entitätsfeld leer. Das unspezifische <code>notify.notify</code> wird nicht akzeptiert. Empfänger, Zugangsdaten und Anbieter richtest du in HA ein, nicht im Widget. Siehe <a href="https://www.home-assistant.io/integrations/notify/" target="_blank" rel="noreferrer">HA-Benachrichtigungen</a>.</p><p>Die Nachrichtentypen E-Mail, WhatsApp, Signal, Pushbullet und Jira beschreiben den eingerichteten Kanal. Die Auswahl installiert keinen Anbieter und wechselt das HA-Ziel nicht automatisch. Die originale ioBroker-Instanz <code>email.0</code> wird durch deine HA-Aktion ersetzt. Im Original ist bisher nur der E-Mail-Versand implementiert; die Studio-Darstellung verwendet für alle eingerichteten Kanäle denselben HA-Vertrag.</p><p>Überschrift und Priorität werden als Text vor die Nachricht gesetzt, beispielsweise <code>Meinen Vermieter informieren</code> und <code>[urgent]</code>. Die Priorität ist keine anbieterspezifische Zustell- oder Alarmstufe. Grenzen: 10.000 Nachrichtenzeichen, 200 Überschriftszeichen. Entwürfe bleiben bei HA-Zustandsaktualisierungen erhalten, jedoch nur im aktuellen Formular: Seitenwechsel oder Neuladen verwirft sie. Projekt-/Widget-Exporte enthalten die Konfiguration, keine eingegebenen Nachrichten.</p><p><img src="'+i+`" alt="Nachrichtenformular und HA-Zielkonfiguration im Editor"></p><h2 id="fensterstatus-ubersicht" tabindex="-1">Fensterstatus-Übersicht <a class="header-anchor" href="#fensterstatus-ubersicht" aria-label="Permalink to &quot;Fensterstatus-Übersicht&quot;">​</a></h2><p>Unter <strong>Fensterliste</strong> wählst du eine HA-Entität und optional ein Attribut mit einer JSON-Liste. Der Originaldatenpunkt heißt <code>WindowStatesHtmlTableVis2</code>, enthält jedoch JSON. Ohne Entitätsbindung verwendet das Widget die bearbeitbare Vorschau:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wohnzimmer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;seit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 12:30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Küche&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;seit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 11:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>isOpen</code> akzeptiert Boolean-Werte, 1/0 und die Texte <code>true</code>/<code>false</code>, <code>on</code>/<code>off</code>, <code>open</code>/<code>closed</code>. Fehlt der Status, erkennt das Widget die alten Icon-Namen <code>fts_window_1w_open.svg</code> und <code>fts_window_1w.svg</code>, ohne Bilddateien zu laden. Sonst erscheint <strong>Unbekannt</strong>. Raum- und Änderungstexte werden als Text angezeigt, nicht als HTML. Grenzen: 200.000 Zeichen JSON, 500 Räume und 512 Zeichen pro Textfeld.</p><p><strong>Offene Räume: Entität</strong> und ein optionales Attribut liefern eine separate, nicht negative ganzzahlige Anzahl. Gezählt werden Räume mit offenen Fenstern. Ohne diese Bindung wird die Anzahl nur aus einer nicht leeren Liste mit vollständig bekannten Zuständen abgeleitet. Fehlende gebundene Daten verwenden keine Vorschau; eine unbekannte Anzahl wird ausdrücklich angezeigt.</p><p>Unter <strong>Farben</strong> stehen Überschrift, Statuszeile, Raumname offen/geschlossen, letzte Änderung offen/geschlossen und Raumhintergrund. Offen verwendet standardmäßig Rot, geschlossen Grün und dessen Änderungszeit Blau. Die Zuordnung folgt den Feldnamen; die vertauschte Zuordnung des Originals wird nicht übernommen. Statt des ioBroker-Themewerts <code>background.paper</code> gibt es eine eigene Hintergrundfarbe. <strong>Allgemein → Ohne Karte</strong> entfernt den äußeren Kartenhintergrund. Einstellungen bleiben in Projekt und Widget-Export erhalten.</p><p>Deine HA-Entität muss die JSON-Liste bereits bereitstellen; das Widget aggregiert keine einzelnen Fenstersensoren und schreibt keine HA-Zustände. Ein <code>heatingcontrol</code>-Adapter ist nicht erforderlich.</p><p><img src="`+t+`" alt="Fensterstatus-Übersicht mit offenen und geschlossenen Räumen"></p><p>Unter <strong>Allgemein</strong> findest du Überschrift, Anzahl der Serien (1–10), Legende und Darstellung ohne Karte. Die erste Reihe kann die allgemeine Entität verwenden. Jede Gruppe <strong>Daten [N]</strong> bietet eine eigene Entität, ein optionales Attribut, Vorschau-JSON, X-/Y-Schlüssel, Name, Einheit, Farbe, Linie/Balken, linke/rechte Wertachse und Differenzberechnung. Mit einer Entitätsbindung liest das Diagramm ausschließlich deren Zustand oder Attribut. Fehlen Live-Daten, wird kein Vorschau-JSON eingesetzt. Es schreibt keine HA-Zustände.</p><p>Beispiel für Vorschau-JSON oder ein HA-Attribut:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T08:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T09:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T10:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Standard-Schlüssel sind <code>x</code> und <code>value</code>; eigene Schlüssel und Paare <code>[x,y]</code> sind möglich. <strong>Zeit</strong> erwartet ISO-Datumsangaben oder Unix-Millisekunden. <strong>Kategorie</strong> zeigt Texte, beispielsweise Jahreszahlen. Zeitpunkte werden vor der Differenzberechnung sortiert. Fehlende Werte unterbrechen die Linie und Differenzfolge; die erste Differenz hat keinen Vorgänger. Linke und rechte Achse werden unabhängig skaliert.</p><p><strong>X-Achse</strong> bietet den Beschriftungsstandard <code>ddd HH:mm</code>. Unterstützte Tokens: <code>YYYY</code>, <code>MM</code>, <code>DD</code>, <code>ddd</code>, <code>HH</code>, <code>mm</code>, <code>ss</code>. Farben stehen unter <strong>WIDGET → CSS Diagramm</strong>. Bis zu 20.000 Eingabezeilen werden akzeptiert; große Reihen werden auf höchstens 500 Punkte pro Reihe reduziert. Das Widget ruft keine HA-Historie ab: Die gewählte Entität muss das Datenarray bereits bereitstellen.</p><p><img src="`+s+'" alt="Installiertes Set mit Diagrammvorschau"></p><h2 id="balkendiagramm-fur-zwei-wochen" tabindex="-1">Balkendiagramm für zwei Wochen <a class="header-anchor" href="#balkendiagramm-fur-zwei-wochen" aria-label="Permalink to &quot;Balkendiagramm für zwei Wochen&quot;">​</a></h2><p>Die Gruppen <strong>Aktuelle Woche</strong> und <strong>Vorwoche</strong> enthalten je sieben HA-Entitäten für Montag bis Sonntag sowie bearbeitbare Vorschauwerte. Das Widget vergleicht die Tagespaare nebeneinander. Es berechnet keine Wochenhistorie selbst und verschiebt keine Werte beim Wochenwechsel: Deine Sensoren müssen jeweils den passenden Tageswert bereitstellen.</p><p><strong>Wochenwerte anzeigen</strong> entspricht funktional der Originaloption „Sichtbar“: ausgeschaltet zeigt das Widget ausschließlich Vorschauwerte; eingeschaltet liest es ausschließlich die 14 Tagesentitäten. Ungebundene, nicht verfügbare oder nicht numerische Live-Werte ergeben keine Balken. Null ist ein gültiger Wert. Die gesamte Widget-Sichtbarkeit regelst du weiterhin unter <strong>Sichtbarkeit</strong>.</p><p>Unter <strong>Allgemein</strong> stellst du Überschrift und Farbe, Legendentextfarbe, Einheit, Wochenfarben, Achsenbeschriftungsfarbe, Y-Achse links/rechts, 0–5 Dezimalstellen, Legende und <strong>Ohne Karte</strong> ein. <strong>X-Achse</strong> hat eine eigene Farbe. Einheiten und formatierte Werte erscheinen in Legende und Balkenhinweisen; die Wochentage folgen der App-Sprache. Farben werden gemäß deinen Einstellungen verwendet.</p><p><img src="'+r+'" alt="Zwei-Wochen-Balkendiagramm im installierten Set"></p><h2 id="wetter-widget" tabindex="-1">Wetter-Widget <a class="header-anchor" href="#wetter-widget" aria-label="Permalink to &quot;Wetter-Widget&quot;">​</a></h2><p><strong>Datenquelle</strong> bietet <code>home-assistant</code>, <code>json</code> und <code>individual</code>. <strong>Datenstruktur</strong> wählt fünf Tageswerte (<code>daily</code>) oder bis zu 24 Stundenwerte (<code>hourly</code>). Die Quellen ersetzen die ioBroker-Instanz- und OID-Auswahl durch HA-Bindungen.</p><p>Bei <code>home-assistant</code> wählst du eine <code>weather.*</code>-Entität. Der Studio-Server liest die Vorhersage über <a href="https://www.home-assistant.io/integrations/weather/" target="_blank" rel="noreferrer">weather.get_forecasts</a>. Erfolgreiche Antworten werden fünf Minuten zwischengespeichert; nach Fehlern erfolgt frühestens nach einer Minute ein neuer Versuch. Die Wetterintegration muss den gewählten Vorhersagetyp unterstützen. Temperatur- und Niederschlagseinheiten stammen aus deren Attributen. Ein echter HA-Abruf erfordert die laufende Add-on-/Supervisor-Anbindung.</p><p>Bei <code>json</code> liest das Widget das gewählte <strong>Vorhersageattribut (JSON)</strong>; leer bedeutet Entitätszustand. Erwartet wird ein Array, beispielsweise:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;datetime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T12:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;templow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cloud_coverage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation_probability&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Bei <code>individual</code> bindest du <strong>Tagesdatum [1–5]</strong> beziehungsweise <strong>Zeitpunkte [1–24]</strong> sowie die zugehörigen Temperatur-, Regen-, Wolken- und Wahrscheinlichkeitswerte an einzelne Sensoren. Zeitangaben sind ISO-Daten oder Unix-Millisekunden. Tagesansichten verwenden nur die ersten fünf Bindungen jeder Wertegruppe. Ungültige Zeitpunkte werden ausgelassen, fehlende Werte unterbrechen Linien; Null ist gültig. Ohne gebundene Wetter-/JSON-Entität zeigen die ersten beiden Quellen die bearbeitbaren Vorschau-Daten. Fehlende Live-Daten ersetzen sie niemals durch Vorschauwerte.</p><p><strong>Temperatur</strong>, <strong>Regen</strong>, <strong>Wolken</strong> und <strong>Regenwahrscheinlichkeit</strong> sind einzeln aktivierbar. Jede Gruppe hat Farben und eine linke/rechte Wertachse; Regen erscheint als Balken. <strong>Im zweiten Diagramm anzeigen</strong> erzeugt eine eigene Diagrammfläche. Unterschiedliche Einheiten auf derselben Achse werden automatisch getrennt. <strong>Sonne oder Wolken</strong> zeigt Wolkenbedeckung oder deren Gegenanteil in Prozent, keine Sonnenstunden. Fehlende Anbieterwerte werden nicht aus Wetterzuständen geschätzt. Name, optionale Standort-Entität, Legende, Farben, X-Datumsformat, Größe und <strong>Ohne Karte</strong> sind einstellbar.</p><p><img src="'+a+'" alt="Wetter-Widget mit Temperatur und Regen"></p><h2 id="ubersicht-uber-heizraume" tabindex="-1">Übersicht über Heizräume <a class="header-anchor" href="#ubersicht-uber-heizraume" aria-label="Permalink to &quot;Übersicht über Heizräume&quot;">​</a></h2><p>Ab <strong>0.1.190</strong> zeigt dieses Widget eine fertige HTML-Raumtabelle, entsprechend dem Original-Datenpunkt <code>RoomStatesHtmlTable</code>. Unter <strong>Raumtabelle</strong> wählst du eine HA-Entität und optional ein <strong>Tabellenattribut</strong>. Ohne Attribut wird der Zustand gelesen. Bei einer Bindung verwendet das Widget ausschließlich diesen Live-Wert; fehlende oder nicht verfügbare Werte zeigen <strong>Keine Raumtabelle verfügbar</strong>. Ohne Entitätsbindung lässt sich <strong>Vorschau-Raumtabelle (HTML)</strong> bearbeiten, auch über den HTML-Editor.</p><p>Das Widget erzeugt keine Raumdaten oder Heizprofile und steuert keine Thermostate. Eine ioBroker-Instanz wie <code>heatingcontrol.0</code> wird nicht benötigt; die gewählte HA-Quelle muss die Tabelle bereits als HTML-String bereitstellen. Lange HTML-Inhalte gehören üblicherweise in ein Attribut statt in den Zustand.</p><p><strong>Allgemein → Ohne Karte</strong>, <strong>Farben → Überschriftenfarbe</strong>, Größe und die gemeinsamen CSS-Einstellungen sind verfügbar. Tabellen, Textformatierung, Zellspannen und ausgewählte Farben/Abstände werden übernommen. Skripte, Ereignishandler, Formulare, Einbettungen und externe Ressourcen werden entfernt. Eingaben sind auf 200.000 Zeichen, die Darstellung auf 5.000 Knoten und 40 Verschachtelungsebenen begrenzt. Große Tabellen scrollen innerhalb des Widgets. Alle Einstellungen bleiben im Widget-/Projektexport erhalten.</p><p><img src="'+d+'" alt="Heizraumübersicht mit Vorschautabelle"></p><h2 id="meteored-wetter-widget" tabindex="-1">METEORED-Wetter-Widget <a class="header-anchor" href="#meteored-wetter-widget" aria-label="Permalink to &quot;METEORED-Wetter-Widget&quot;">​</a></h2><p>Ab <strong>0.1.191</strong> findest du unter <strong>Allgemein</strong> die Optionen <strong>Ohne Karte</strong>, <strong>Meteored-Widget-ID</strong> und <strong>Neuladen aktivieren</strong>. Erstelle dein Widget bei <a href="https://www.daswetter.com/widget/" target="_blank" rel="noreferrer">Meteored / daswetter.com</a> und trage ausschließlich dessen ID ein, keinen vollständigen HTML-Code und keine URL. Erlaubt sind 1–128 Buchstaben, Ziffern, Unterstriche oder Bindestriche. Gib beim Anbieter die Domain frei, unter der du die Runtime tatsächlich aufrufst.</p><p>Die Runtime lädt den offiziellen Loader <code>https://api.meteored.com/widget/loader/ID</code> in einem separaten Frame. Internetzugriff und eine gültige Anbieter-Konfiguration sind erforderlich. <strong>Neuladen aktivieren</strong> ist standardmäßig eingeschaltet und lädt einmal pro Stunde neu. Ausschalten beendet den Timer; ID-Wechsel und Entfernen räumen den alten Timer auf. Normale Runtime-Neuzeichnungen starten den Frame und seinen Timer nicht erneut. Im Editor siehst du eine Konfigurationsvorschau; eine leere oder ungültige ID lädt nichts.</p><p>Der Frame hat <code>sandbox=&quot;allow-scripts&quot;</code>; die Loader-Seite erhält dieselbe Sandbox über ihren HTTP-Header. Meteored-Code läuft damit ohne Zugriff auf den Studio-DOM. Das Widget benötigt keine HA-Entität und übernimmt Standort, Sprache und Gestaltung aus deiner Meteored-Konfiguration. Alle drei Optionen sowie Größe und CSS bleiben im Export erhalten. Eine vollständige Prüfung der Anbieteranzeige benötigt deine echte Widget-ID und freigegebene Domain.</p><p><img src="'+l+'" alt="METEORED-Konfiguration im Editor"></p><p>Der reproduzierbare Paketbau und das geprüfte Manifest stehen im <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/weather-heating" target="_blank" rel="noreferrer">Quellcode</a>. Der <a href="./widget-pakete">Paketvertrag</a> beschreibt Schnittstelle 0.2.</p>',58)])])}const y=o(p,[["render",c]]);export{z as __pageData,y as default};
